struct Pcg {state:u128,inc:u128,buffer:Option<u32>}
impl Pcg {
    fn seeded(seed:u64)->Self {let (state,inc)=match seed{20260515=>(300936217048912661423338589542005123575,247270855025706022817204781204357037513),0=>(35399562948360463058890781895381311971,87136372517582989555478159403783844777),_=>unreachable!()};Self{state,inc,buffer:None}}
    fn u64(&mut self)->u64{self.state=self.state.wrapping_mul(47026247687942121848144207491837523525).wrapping_add(self.inc);let hi=(self.state>>64) as u64;let lo=self.state as u64;(hi^lo).rotate_right((hi>>58) as u32)}
    fn uniform(&mut self)->f64{(self.u64()>>11) as f64*(1./9007199254740992.)}
    fn u32(&mut self)->u32{if let Some(v)=self.buffer.take(){v}else{let v=self.u64();self.buffer=Some((v>>32) as u32);v as u32}}
    fn bounded(&mut self,max:usize)->usize{if max==0{return 0;}let range=max as u32+1;let threshold=range.wrapping_neg()%range;loop{let v=self.u32() as u64*range as u64;if v as u32>=threshold{return (v>>32) as usize;}}}
    fn normal(&mut self)->f64{loop{let mut r=self.u64();let idx=(r&255) as usize;r>>=8;let sign=r&1;let a=(r>>1)&0x000fffffffffffff;let mut x=a as f64*WI_DOUBLE[idx];if sign!=0{x=-x;}if a<KI_DOUBLE[idx]{return x;}if idx==0{loop{let xx=-(1./3.6541528853610088)*(-self.uniform()).ln_1p();let yy=-(-self.uniform()).ln_1p();if yy+yy>xx*xx{return if (a>>8)&1!=0{-(3.6541528853610088+xx)}else{3.6541528853610088+xx};}}}else if (FI_DOUBLE[idx-1]-FI_DOUBLE[idx])*self.uniform()+FI_DOUBLE[idx]<(-0.5*x*x).exp(){return x;}}}
}
fn hull_indices(pop:usize)->Vec<usize>{let size=pop.min(8000);let mut rng=Pcg::seeded(0);let mut ids;if pop>10000&&size>pop/50{ids=(0..pop).collect::<Vec<_>>();for i in (std::cmp::max(pop-size,1)..pop).rev(){let j=rng.bounded(i);ids.swap(i,j);}ids=ids.split_off(pop-size);}else{ids=Vec::with_capacity(size);let mut set=BTreeSet::new();for j in pop-size..pop{let val=rng.bounded(j);let value=if set.contains(&val){j}else{val};set.insert(value);ids.push(value);}for i in (1..size).rev(){let j=rng.bounded(i);ids.swap(i,j);}}ids}
fn cross(a:[f64;3],b:[f64;3])->[f64;3]{[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]}
fn diff(a:[f64;3],b:[f64;3])->[f64;3]{std::array::from_fn(|i|a[i]-b[i])}
fn dot(a:[f64;3],b:[f64;3])->f64{(0..3).map(|i|a[i]*b[i]).sum()}
fn volume(points:&[[f64;3]])->Result<f64,String>{
    if points.len()<4{return Err("gamut hull needs four noncoplanar points".into());}
    let a=0;let b=(1..points.len()).max_by(|&i,&j|distance(points[i],points[a]).total_cmp(&distance(points[j],points[a]))).unwrap();let c=(0..points.len()).max_by(|&i,&j|dot(cross(diff(points[b],points[a]),diff(points[i],points[a])),cross(diff(points[b],points[a]),diff(points[i],points[a]))).total_cmp(&dot(cross(diff(points[b],points[a]),diff(points[j],points[a])),cross(diff(points[b],points[a]),diff(points[j],points[a]))))).unwrap();let normal=cross(diff(points[b],points[a]),diff(points[c],points[a]));let d=(0..points.len()).max_by(|&i,&j|dot(normal,diff(points[i],points[a])).abs().total_cmp(&dot(normal,diff(points[j],points[a])).abs())).unwrap();
    if dot(normal,diff(points[d],points[a])).abs()<1e-14{return Err("degenerate gamut hull (collapsed output)".into());}
    let center=std::array::from_fn(|i|(points[a][i]+points[b][i]+points[c][i]+points[d][i])/4.);
    let orient=|mut f:[usize;3]|{if dot(cross(diff(points[f[1]],points[f[0]]),diff(points[f[2]],points[f[0]])),diff(center,points[f[0]]))>0.{f.swap(1,2);}f};
    let mut faces=vec![orient([a,b,c]),orient([a,d,b]),orient([a,c,d]),orient([b,d,c])];
    for (i,p) in points.iter().enumerate(){if [a,b,c,d].contains(&i){continue;}let mut edges:BTreeMap<(usize,usize),(usize,usize)>=BTreeMap::new();faces.retain(|f|{let n=cross(diff(points[f[1]],points[f[0]]),diff(points[f[2]],points[f[0]]));let visible=dot(n,diff(*p,points[f[0]]))>1e-12*dot(n,n).sqrt();if visible{for (u,v) in [(f[0],f[1]),(f[1],f[2]),(f[2],f[0])]{let k=(u.min(v),u.max(v));if edges.remove(&k).is_none(){edges.insert(k,(u,v));}}} !visible});for (_, (u,v)) in edges{faces.push(orient([u,v,i]));}}
    Ok(faces.iter().map(|f|dot(diff(points[f[0]],center),cross(diff(points[f[1]],center),diff(points[f[2]],center)))/6.).sum::<f64>().abs())
}
fn locus()->Vec<[f64;2]>{(0..=64).map(|i|{let j=i;xy([spectral::CMF_X_F64[j],spectral::CMF_Y_F64[j],spectral::CMF_Z_F64[j]])}).collect()}
