    let mut r=result("off_grid_identity",json!({"trilinear_dE2000_max":max(&tri),"trilinear_dE2000_p99":percentile(&tri,0.99),"trilinear_dE2000_p50":percentile(&tri,0.5),"tetrahedral_dE2000_max":max(&tet),"tetrahedral_dE2000_p99":percentile(&tet,0.99),"tetrahedral_dE2000_p50":percentile(&tet,0.5),"trilinear_dITP_max":max(&itp),"trilinear_dITP_p99":percentile(&itp,0.99)}),Some(max(&tri)<=2.&&percentile(&tri,0.99)<=1.&&max(&tet)<=2.&&percentile(&tet,0.99)<=1.),"ΔE₀₀","Interpolation error against the full scientific pipeline, including input exposure and output transport scaling.");
    limits(&mut r,&[("trilinear_dE2000_max","≤ 2.0"),("trilinear_dE2000_p99","≤ 1.0"),("tetrahedral_dE2000_max","≤ 2.0"),("tetrahedral_dE2000_p99","≤ 1.0")]);let points:Vec<_>=samples.iter().map(|p|[p[0],p[1]]).collect();let colors:Vec<_>=tri.iter().map(|v|[(v/2.).clamp(0.,1.),0.2,1.-(v/2.).clamp(0.,1.)]).collect();r.figure_path=Some(plot(root,&r.name,&points,&colors)?);results.push(r);
    let mut violations=0;let mut worst=0f64;let mut tv=[0.;3];let mut counts=[0usize;3];for r in 0..n{for g in 0..n{for b in 0..n{let p=[r,g,b];for a in 0..3{if p[a]+1<n{let mut q=p;q[a]+=1;let x=lut.at(r,g,b);let y=lut.at(q[0],q[1],q[2]);let d=y[a]-x[a];if d<0.{violations+=1;worst=worst.min(d);}for c in 0..3{tv[a]+=(y[c]-x[c]).abs();counts[a]+=1;}}}}}}
    let pin=input.encode(0.18/gain);let mut curves=Vec::new();let mut center_violations=0;for axis in 0..3{let mut previous=None;for i in 0..65{let t=i as f64/64.;let mut p=[pin;3];p[axis]=t;let y=lut.sample(p);if previous.is_some_and(|v|y[axis]<v){center_violations+=1;}previous=Some(y[axis]);curves.push([t,1.-y[axis]]);}}
    let mut r=result("monotonicity",json!({"violations":violations,"worst_negative_diff":worst,"centerline_pin_encoded":pin,"centerline_violations":center_violations}),Some(violations==0),"cells","Diagonal axis-channel negative differences are cube-wide fold-backs.");limits(&mut r,&[("violations","== 0"),("worst_negative_diff","== 0 when violations == 0")]);r.figure_path=Some(plot(root,&r.name,&curves,&vec![[0.7,0.8,0.9];curves.len()])?);results.push(r);
    let mut cond=Vec::new();for r in 1..n-1{for g in 1..n-1{for b in 1..n-1{let derivatives=[diff(lut.at(r+1,g,b),lut.at(r-1,g,b)),diff(lut.at(r,g+1,b),lut.at(r,g-1,b)),diff(lut.at(r,g,b+1),lut.at(r,g,b-1))];let s=singular(std::array::from_fn(|i|std::array::from_fn(|j|derivatives[j][i])));cond.push((s[0]/s[2].max(1e-12)).max(1.).log10());}}}
