    for a in 0..3{tv[a]/=counts[a] as f64;}let fft=fft_ratios(lut);let mut r=result("total_variation",json!({"tv":tv.iter().sum::<f64>(),"tv_r":tv[0],"tv_g":tv[1],"tv_b":tv[2],"axial_highband_ratio_r":fft[2],"axial_highband_ratio_g":fft[1],"axial_highband_ratio_b":fft[0],"axial_highband_ratio_mean":mean(&fft)}),None,"","Mean absolute cube finite differences and upper-half axial FFT magnitude energy (Python axis-label convention).");attach(&mut r,root,n*n,n,&lut.table.iter().map(|&p|display(p,output)).collect::<Vec<_>>())?;results.push(r);
