    let mut rim=Vec::new();for axis in 0..3{for a in [0.,1.]{for b in [0.,1.]{for i in 0..96{let mut p=[0.;3];p[axis]=i as f64/95.;p[(axis+1)%3]=a;p[(axis+2)%3]=b;rim.push(p);}}}}
